package dev.cazajefes;

import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.*;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.potion.*;

/** Prepares damage modifiers, then charges and activates only accepted hits. */
final class RareCombat implements Listener {
 private record Proc(String id,int level,float cost){}
 private record Hit(Player player,LivingEntity target,List<Proc> procs,double health){}
 private final CazaJefesPlugin plugin;private final RelicItems items;
 private final Map<EntityDamageByEntityEvent,Hit> pending=new WeakHashMap<>();
 private final Map<UUID,Long> hungerReady=new HashMap<>();
 private final Map<String,Long> rareReady=new HashMap<>();
 private final NamespacedKey arrow=new NamespacedKey("cazajefes","infused_projectile");
 private boolean secondary;
 RareCombat(CazaJefesPlugin plugin,RelicItems items){this.plugin=plugin;this.items=items;}
 static boolean behind(double dot){return dot<-.05;}
 static boolean accepted(boolean cancelled,double damage){return !cancelled&&Double.isFinite(damage)&&damage>0;}
 static boolean enemy(Player a,Player b){if(a.equals(b)||!CombatGuard.eligible(b)||!a.getWorld().getPVP())return false;var team=a.getScoreboard().getEntryTeam(a.getName());return team==null||!team.hasEntry(b.getName());}
 private Map<String,Integer> powers(ItemStack item){return items.activeProperties(item);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void trident(ProjectileLaunchEvent e){if(e.getEntity() instanceof Trident trident&&trident.getShooter() instanceof Player){String data=powers(trident.getItemStack()).entrySet().stream().filter(v->(RareCompatibility.property(v.getKey())==RareCompatibility.Group.RANGED||RareCompatibility.property(v.getKey())==RareCompatibility.Group.BOW)).map(v->v.getKey()+":"+v.getValue()).collect(java.util.stream.Collectors.joining(","));if(!data.isEmpty())trident.getPersistentDataContainer().set(arrow,PersistentDataType.STRING,data);}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void shoot(EntityShootBowEvent e){if(e.getEntity() instanceof Player){String data=powers(e.getBow()).entrySet().stream().filter(v->(RareCompatibility.property(v.getKey())==RareCompatibility.Group.RANGED||RareCompatibility.property(v.getKey())==RareCompatibility.Group.BOW)).map(v->v.getKey()+":"+v.getValue()).collect(java.util.stream.Collectors.joining(","));if(!data.isEmpty())e.getProjectile().getPersistentDataContainer().set(arrow,PersistentDataType.STRING,data);}}
 private Map<String,Integer> snapshot(EntityDamageByEntityEvent e,Player player){if(!(e.getDamager() instanceof Projectile shot))return powers(player.getInventory().getItemInMainHand());Map<String,Integer> out=new LinkedHashMap<>();String data=shot.getPersistentDataContainer().get(arrow,PersistentDataType.STRING);if(data!=null)for(String value:data.split(",")){String[] pair=value.split(":");if(pair.length==2)try{if(RareDefinitions.get(pair[0])!=null&&(RareCompatibility.property(pair[0])==RareCompatibility.Group.RANGED||RareCompatibility.property(pair[0])==RareCompatibility.Group.BOW))out.put(pair[0],RareDefinitions.limited(pair[0],Integer.parseInt(pair[1])));}catch(NumberFormatException ignored){}}return out;}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void prepare(EntityDamageByEntityEvent e){
  if(secondary||RangedRares.secondary||JailRares.secondary||!accepted(e.isCancelled(),e.getFinalDamage())||!(e.getEntity() instanceof LivingEntity target))return;Entity source=e.getDamager();if(source instanceof Projectile p&&p.getShooter() instanceof Entity owner)source=owner;if(!(source instanceof Player player)||!CombatGuard.eligible(player)||target instanceof Player victim&&!enemy(player,victim))return;
  Map<String,Integer> powers=snapshot(e,player);List<Proc> procs=new ArrayList<>();float available=player.getSaturation();ItemStack held=player.getInventory().getItemInMainHand();
  for(var entry:powers.entrySet()){String id=entry.getKey();int n=entry.getValue();if(System.currentTimeMillis()<rareReady.getOrDefault(player.getUniqueId()+":"+id,0L))continue;boolean trigger=switch(id){case "backstab"->{var v=player.getLocation().toVector().subtract(target.getLocation().toVector()).setY(0);var facing=target.getLocation().getDirection().setY(0);yield v.lengthSquared()>.001&&facing.lengthSquared()>.001&&behind(facing.normalize().dot(v.normalize()))&&Math.random()<RareBalance.chance(id,n)&&!(target instanceof Player victim&&items.armorCounter(victim,"turtle"));}case "execute"->target.getHealth()/target.getMaxHealth()<RareDefinitions.executeThreshold(n)&&Math.random()<RareBalance.chance(id,n);case "vampiricregeneration","vampirismo"->Math.random()<RareBalance.chance(id,n)&&!(target instanceof Player victim&&items.armorCounter(victim,"garlic"));case "calllighting"->Math.random()<RareBalance.chance(id,n);case "poison","veneno","bleed"->Math.random()<RareBalance.chance(id,n);case "disarm"->target instanceof Player victim&&!victim.getInventory().getItemInMainHand().getType().isAir()&&victim.getInventory().firstEmpty()>=0&&Math.random()<RareBalance.chance(id,n);case "blinding","confuse","slow","weaken","brasas"->Math.random()<RareBalance.chance(id,n);default->false;};if(!trigger)continue;var definition=RareDefinitions.get(id);float cost=items.saturationCost(held,id);if(cost<0||cost>available)continue;available-=cost;procs.add(new Proc(id,n,cost));if(id.equals("backstab"))SafeDamage.scale(e,1+RareBalance.damage(id,.5));if(id.equals("execute"))SafeDamage.scale(e,1+RareBalance.damage(id,1));if(id.equals("calllighting"))e.setDamage(EntityDamageEvent.DamageModifier.BASE,e.getDamage()+RareBalance.damage(id,2*n));}
  pending.put(e,new Hit(player,target,procs,target.getHealth()));
 }
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void commit(EntityDamageByEntityEvent e){Hit hit=pending.remove(e);if(hit==null||!accepted(e.isCancelled(),e.getFinalDamage()))return;double dealt=Math.min(e.getFinalDamage(),hit.health());for(Proc proc:hit.procs()){if(hit.player().getSaturation()<proc.cost())continue;var definition=RareDefinitions.get(proc.id());int cooldown=RareBalance.cooldown(proc.id(),definition==null?0:definition.cooldown());if(cooldown>0)rareReady.put(hit.player().getUniqueId()+":"+proc.id(),System.currentTimeMillis()+cooldown*1000L);hit.player().setSaturation(Math.max(0,hit.player().getSaturation()-proc.cost()));plugin.getServer().getScheduler().runTask(plugin,()->activate(hit,proc,dealt));}if(!(e.getDamager() instanceof Projectile))stealFood(hit.player(),hit.target());}
 private void activate(Hit hit,Proc proc,double dealt){Player a=hit.player();LivingEntity v=hit.target();if(!a.isOnline()||a.isDead())return;int n=proc.level();String id=proc.id();if(id.equals("vampiricregeneration")||id.equals("vampirismo")){double amount=RareBalance.healing(id,Math.min(3+n,dealt*(.2+.05*n)));var heal=new EntityRegainHealthEvent(a,amount,EntityRegainHealthEvent.RegainReason.CUSTOM);Bukkit.getPluginManager().callEvent(heal);if(!heal.isCancelled()&&Double.isFinite(heal.getAmount())&&heal.getAmount()>0)a.setHealth(Math.min(a.getMaxHealth(),a.getHealth()+Math.min(amount,heal.getAmount())));return;}if(!v.isValid()||v.isDead()||!a.getWorld().equals(v.getWorld())||v instanceof Player p&&!enemy(a,p))return;
  switch(id){case "poison","veneno"->effect(v,PotionEffectType.POISON,RareBalance.ticks(id,80),n-1);case "blinding"->effect(v,PotionEffectType.BLINDNESS,RareBalance.ticks(id,60),0);case "confuse"->effect(v,PotionEffectType.NAUSEA,RareBalance.ticks(id,100),0);case "slow"->effect(v,PotionEffectType.SLOWNESS,RareBalance.ticks(id,20*(3+n)),0);case "weaken"->effect(v,PotionEffectType.WEAKNESS,RareBalance.ticks(id,20*(3+n)),0);case "bleed"->effect(v,PotionEffectType.WITHER,RareBalance.ticks(id,40*n),0);case "brasas"->v.setFireTicks(Math.max(v.getFireTicks(),RareBalance.ticks(id,40+20*n)));case "disarm"->{if(v instanceof Player p){var inv=p.getInventory();int slot=inv.firstEmpty();ItemStack weapon=inv.getItemInMainHand();if(slot>=0&&!weapon.getType().isAir()&&slot!=inv.getHeldItemSlot()){inv.setItem(slot,weapon.clone());inv.setItemInMainHand(null);p.playSound(p.getLocation(),Sound.ITEM_ARMOR_EQUIP_CHAIN,.6f,.8f);}}}case "calllighting"->{v.getWorld().strikeLightningEffect(v.getLocation());a.sendMessage("§bVeredicto de la Tormenta §7» Descarga activada contra el objetivo.");}default->{}}
 }
 void effect(LivingEntity target,PotionEffectType type,int duration,int amplifier){int clarity=target instanceof Player p?items.armorLevel(p,"clarity"):0;int ticks=(type==PotionEffectType.BLINDNESS||type==PotionEffectType.NAUSEA)?RareDefinitions.clarityTicks(duration,clarity):duration;target.addPotionEffect(new PotionEffect(type,ticks,Math.max(0,Math.min(3,amplifier))));}
 private void stealFood(Player player,LivingEntity target){if(!(target instanceof Player victim)||!enemy(player,victim))return;int n=items.armorLevel(player,"hungersteal");long now=System.currentTimeMillis();if(n<=0||now<hungerReady.getOrDefault(player.getUniqueId(),0L))return;int amount=Math.min(n,Math.min(victim.getFoodLevel(),20-player.getFoodLevel()));if(amount<=0)return;victim.setFoodLevel(victim.getFoodLevel()-amount);victim.setSaturation(Math.min(victim.getSaturation(),victim.getFoodLevel()));player.setFoodLevel(player.getFoodLevel()+amount);hungerReady.put(player.getUniqueId(),now+10000);}
 private final Map<UUID,Long> blindReady=new HashMap<>();
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void helmetBlind(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof Player victim)||!(e.getDamager() instanceof LivingEntity attacker)||!accepted(e.isCancelled(),e.getFinalDamage())||!CombatGuard.eligible(victim)||attacker instanceof Player p&&!enemy(victim,p))return;int level=items.activePropertyLevel(victim.getInventory().getHelmet(),"blinding");long now=System.currentTimeMillis();if(level<=0||now<blindReady.getOrDefault(victim.getUniqueId(),0L)||Math.random()>=RareBalance.chance("blinding",level))return;var helmet=victim.getInventory().getHelmet();float cost=items.saturationCost(helmet,"blinding");if(cost<0||victim.getSaturation()<cost)return;victim.setSaturation(victim.getSaturation()-cost);blindReady.put(victim.getUniqueId(),now+RareBalance.cooldown("blinding",8)*1000L);plugin.getServer().getScheduler().runTask(plugin,()->{if(attacker.isValid()&&!attacker.isDead()){effect(attacker,PotionEffectType.BLINDNESS,RareBalance.ticks("blinding",60),0);victim.sendMessage("§bVelo del Eclipse §7» Represalia de ceguera activada.");}});}
 @EventHandler public void quit(PlayerQuitEvent e){plugin.getServer().getScheduler().runTaskLater(plugin,()->{long now=System.currentTimeMillis();hungerReady.values().removeIf(end->end<=now);rareReady.values().removeIf(end->end<=now);},220);}
 void stop(){pending.clear();hungerReady.clear();blindReady.clear();rareReady.clear();}
}
